# Workflow: add a cover page with title 'Annual Financial Report' to report.pdf
python3 -m pip list 2>/dev/null | grep -iE "fpdf|matplotlib|weasy|fitz|pymupdf|borb|pdfkit|reportlab|pikepdf|img2pdf|svglib|fpdf2" ;
for b in pandoc libreoffice soffice wkhtmltopdf gs pdflatex xelatex enscript a2ps cupsfilter ps2pdf convert; do command -v $b >/dev/null 2>&1 && echo "BIN: $b"; done; echo done
